import{_ as d,o as r,c as a,a5 as e}from"./chunks/framework.bIR-4glx.js";const g=JSON.parse('{"title":"词汇证据卡：从卡片眼熟到情境调用","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/vocabulary-audit.zh.md","filePath":"public/downloads/worksheets/vocabulary-audit.zh.md","lastUpdated":1795488252000}'),h={name:"public/downloads/worksheets/vocabulary-audit.zh.md"};function l(b,t,i,o,n,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="词汇证据卡-从卡片眼熟到情境调用" tabindex="-1">词汇证据卡：从卡片眼熟到情境调用 <a class="header-anchor" href="#词汇证据卡-从卡片眼熟到情境调用" aria-label="Permalink to &quot;词汇证据卡：从卡片眼熟到情境调用&quot;">​</a></h1><p>把这张卡复制到私有笔记中，一次只记录一个真实主题或任务。不要写入密码、客户资料、未公开文档、考试答案、医疗隐私或未获许可的第三方内容。最终词表可以公开，不代表原始材料、录音和反馈也可以公开。</p><h2 id="_1-定义任务与证据条件" tabindex="-1">1. 定义任务与证据条件 <a class="header-anchor" href="#_1-定义任务与证据条件" aria-label="Permalink to &quot;1. 定义任务与证据条件&quot;">​</a></h2><h3 id="vocabulary-evidence-yyyy-mm-dd" tabindex="-1">Vocabulary Evidence - YYYY-MM-DD <a class="header-anchor" href="#vocabulary-evidence-yyyy-mm-dd" aria-label="Permalink to &quot;Vocabulary Evidence - YYYY-MM-DD&quot;">​</a></h3><p>真实场景与受众：<br> 任务：听 / 读 / 说 / 写 / 考试 / 交接<br> 材料、版本与来源：<br> 完成后对方应理解、决定或完成什么：<br> 时间与长度限制：<br> 允许的字幕 / 词典 / 翻译 / 搜索 / AI / 人工帮助：<br> 隐私、版权、保密、考试与专业责任边界：<br> 首遇日期：<br> 平行任务日期：</p><p>词汇目标不是“新增多少”，而是在这些条件下理解、选对并及时调用。</p><h2 id="_2-保存未经查词的首遇" tabindex="-1">2. 保存未经查词的首遇 <a class="header-anchor" href="#_2-保存未经查词的首遇" aria-label="Permalink to &quot;2. 保存未经查词的首遇&quot;">​</a></h2><p>首遇开始/结束时间：<br> 不查词时理解的主旨、关系与下一步：<br> 确定理解的细节：<br> 需要猜测的位置：<br> 让我停住的原句或时间段：<br> 当时尝试的义项/表达：<br> 原始复述、录音、填空或写作位置：<br> 首遇是否完成真实任务：是 / 部分 / 否</p><p>先判断障碍是否真是词汇：声音切分、句法、背景、版面和注意力也可能让一句话失败。</p><h2 id="_3-建立未知项决策队列" tabindex="-1">3. 建立未知项决策队列 <a class="header-anchor" href="#_3-建立未知项决策队列" aria-label="Permalink to &quot;3. 建立未知项决策队列&quot;">​</a></h2><table tabindex="0"><thead><tr><th>词/词块</th><th>任务影响</th><th>决定</th><th>当时依据</th><th>下一检查点</th></tr></thead><tbody><tr><td></td><td>阻断 / 重要 / 次要 / 无影响</td><td>放过 / 推断 / 速查 / 学习 / 专业核验</td><td></td><td></td></tr></tbody></table><p>本轮进入主动学习的 5-8 个词块：<br> 可以放过的词及理由：<br> 必须由一手来源或专业人员核验的词：<br> 因容量不足暂缓的词：</p><h2 id="_4-为每个高价值词块记录八个维度" tabindex="-1">4. 为每个高价值词块记录八个维度 <a class="header-anchor" href="#_4-为每个高价值词块记录八个维度" aria-label="Permalink to &quot;4. 为每个高价值词块记录八个维度&quot;">​</a></h2><p>每个词块复制一次：</p><p>词/词块：<br> 任务功能：<br> 词形、屈折与派生：<br> 声音、重音与自然语流：<br> 当前义项（自己的话）：<br> 常见搭配或句型槽位：<br> 语法行为：<br> 语域、礼貌、立场与身份：<br> 概念、现实指代、版本或领域边界：<br> 当前调用时间与所需提示：<br> 一个近义项/反例及差异：</p><p>不要为了填满栏目抄整页词典。只保留会改变当前理解或使用的内容。</p><h2 id="_5-核验义项、搭配与来源" tabindex="-1">5. 核验义项、搭配与来源 <a class="header-anchor" href="#_5-核验义项、搭配与来源" aria-label="Permalink to &quot;5. 核验义项、搭配与来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>待核对内容</th><th>我的候选</th><th>来源、版本与位置</th><th>核验结果</th><th>仍未知</th></tr></thead><tbody><tr><td>义项</td><td></td><td></td><td></td><td></td></tr><tr><td>发音</td><td></td><td></td><td></td><td></td></tr><tr><td>搭配</td><td></td><td></td><td></td><td></td></tr><tr><td>语域</td><td></td><td></td><td></td><td></td></tr><tr><td>技术/制度概念</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>词典或语料为什么适合这个任务：<br> 一手文档/标准/代码位置：<br> 查证日期：<br> 谁对高风险术语作最终判断：<br> 什么新证据会改变当前决定：</p><p>AI 生成的例句和解释是候选，不是来源。高风险术语不能只靠使用频率或模型语气裁决。</p><h2 id="_6-设计无提示调用" tabindex="-1">6. 设计无提示调用 <a class="header-anchor" href="#_6-设计无提示调用" aria-label="Permalink to &quot;6. 设计无提示调用&quot;">​</a></h2><p>真实意图或情境线索：<br> 第一轮允许的提示：<br> 下一轮将撤掉的提示：<br> 目标调用时间：<br> 口头任务：<br> 书面任务：<br> 改变的人物 / 时间 / 主题 / 语气 / 模态：</p><table tabindex="0"><thead><tr><th>尝试</th><th>条件</th><th>我的实际表达</th><th style="text-align:right;">调用时间</th><th>结果</th></tr></thead><tbody><tr><td>原情境</td><td>无答案展示</td><td></td><td style="text-align:right;"></td><td></td></tr><tr><td>改变情境</td><td>撤掉原句</td><td></td><td style="text-align:right;"></td><td></td></tr><tr><td>真实任务</td><td>有受众与后果</td><td></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>若只能完整背出原句，先不要记作迁移成功。</p><h2 id="_7-让真实读者或听众验收" tabindex="-1">7. 让真实读者或听众验收 <a class="header-anchor" href="#_7-让真实读者或听众验收" aria-label="Permalink to &quot;7. 让真实读者或听众验收&quot;">​</a></h2><p>读者/听众复述的意思：<br> 他理解的关系、确定性和下一步：<br> 需要猜测或确认的位置：<br> 词汇是否改变事实或责任：<br> 是否完成任务：是 / 部分 / 否<br> 真实回应或执行结果：</p><table tabindex="0"><thead><tr><th>反馈</th><th>类型</th><th>决定</th><th>理由</th><th>是否进入平行任务</th></tr></thead><tbody><tr><td></td><td>必要修复 / 可接受变体 / 语域 / 风格</td><td>采纳 / 部分 / 拒绝 / 延后</td><td></td><td></td></tr></tbody></table><h2 id="_8-记录错误与最小修复" tabindex="-1">8. 记录错误与最小修复 <a class="header-anchor" href="#_8-记录错误与最小修复" aria-label="Permalink to &quot;8. 记录错误与最小修复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误样本</th><th>类型</th><th>可能缺口</th><th>下一次只改什么</th><th>复测条件</th></tr></thead><tbody><tr><td></td><td>词形 / 声音 / 义项 / 搭配 / 语法 / 语域 / 调用慢 / 迁移失败</td><td></td><td></td><td></td></tr></tbody></table><p>卡片答对但任务失败的词块：<br> 听得懂却写不出的词块：<br> 看得懂却听不出的词块：<br> 可以接受但被误判成错误的变体：<br> 需要拆卡、降量或补背景的项目：</p><h2 id="_9-记录-ai-与工具使用" tabindex="-1">9. 记录 AI 与工具使用 <a class="header-anchor" href="#_9-记录-ai-与工具使用" aria-label="Permalink to &quot;9. 记录 AI 与工具使用&quot;">​</a></h2><p>工具 / 模型 / 版本与日期：<br> 使用前已经存在的首遇和候选：<br> 请求：义项比较 / 搭配候选 / 填空 / 反例 / 受众模拟<br> / 错误分类 / 平行任务 / 其他<br> 模型生成或改写的范围：<br> 可能捏造或过时的内容：<br> 词典 / 语料 / 一手文档 / 人工核验：<br> 我采纳、拒绝与延后的项目及理由：<br> 关闭工具后的调用任务：</p><h2 id="_10-做延迟保持与迁移" tabindex="-1">10. 做延迟保持与迁移 <a class="header-anchor" href="#_10-做延迟保持与迁移" aria-label="Permalink to &quot;10. 做延迟保持与迁移&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>撤掉什么</th><th>改变什么</th><th>输出</th><th>结果</th></tr></thead><tbody><tr><td>当天</td><td>答案与释义</td><td>原主题</td><td>情境回忆</td><td></td></tr><tr><td>第 1 天</td><td>原句</td><td>句子与人物</td><td>口头/书面调用</td><td></td></tr><tr><td>第 3-7 天</td><td>最近提示</td><td>模态或受众</td><td>平行输入/输出</td><td></td></tr><tr><td>第 14 天</td><td>旧卡与即时反馈</td><td>新主题、同任务</td><td>限时真实输出</td><td></td></tr><tr><td>第 30 天</td><td>全部练习提示</td><td>真实材料与后果</td><td>完整交付</td><td></td></tr></tbody></table><p>仍能及时调用的词块：<br> 只在原题中成功的词块：<br> 最常复发的错误：<br> 真实任务是否减少猜测或返工：</p><h2 id="_11-评分并决定保留什么" tabindex="-1">11. 评分并决定保留什么 <a class="header-anchor" href="#_11-评分并决定保留什么" aria-label="Permalink to &quot;11. 评分并决定保留什么&quot;">​</a></h2><p>每项 <code>0-2</code> 分：<code>0=无证据或未完成</code>，<code>1=依赖提示或不稳定</code>，<code>2=当前条件下独立完成</code>。</p><table tabindex="0"><thead><tr><th>项目</th><th style="text-align:right;">当天</th><th style="text-align:right;">第 7 天</th><th style="text-align:right;">第 14 天</th><th>证据理由</th></tr></thead><tbody><tr><td>在声音和文字中识别</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>判断当前义项与任务影响</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>使用合适搭配、词形与语域</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>在时限内无提示调用</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>让读者/听众收到预期意思</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>换主题、受众或模态后迁移</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>继续学习的词块及理由：<br> 需要拆分或更换线索的词块：<br> 可以归档的词块：<br> 必须专业核验的词块：<br> 下一轮只改变的一个条件：<br> 下次复查日期：</p><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-1/2-vocabulary" target="_blank" rel="noreferrer">词汇篇：从眼熟到在真实任务中调用</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/3-listening" target="_blank" rel="noreferrer">听力篇</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/4-reading" target="_blank" rel="noreferrer">阅读篇</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/5-speaking" target="_blank" rel="noreferrer">口语篇</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/6-writing" target="_blank" rel="noreferrer">写作篇</a> ｜ <a href="https://byoungd.github.io/up/threads/part-1/7-ai" target="_blank" rel="noreferrer">用 AI 学英语</a></p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/vocabulary-audit" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-09-02。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',42)])])}const u=d(h,[["render",l]]);export{g as __pageData,u as default};
